package org.diy.liferecorder;
import android.content.*;import android.os.*;import android.media.MediaRecorder;import android.widget.*;import android.view.Gravity;import java.io.*;
/** User-started foreground voice memo. Leaving this screen stops and saves the memo. */
public final class VoiceMemoActivity extends AppScreen {
 private String savedId="";private MediaRecorder recorder;private File pending;private long started;private boolean saving;private final Handler clock=new Handler();private TextView elapsed;private Button start,stop;
 private final Runnable tick=new Runnable(){public void run(){if(recorder==null)return;long seconds=(SystemClock.elapsedRealtime()-started)/1000;elapsed.setText(String.format(java.util.Locale.ROOT,"%02d:%02d",seconds/60,seconds%60));if(seconds>=1800){save();return;}clock.postDelayed(this,500);}};
 public void onCreate(Bundle b){super.onCreate(b);frame("语音备忘");button(body,"‹ 返回",this::finish);LinearLayout memo=card(body);memo.addView(title("记下此刻的声音",25));memo.addView(text("点击开始后使用手机麦克风。离开此页会停止并保存；最长 30 分钟。",14,MUTED));elapsed=title("00:00",38);elapsed.setGravity(Gravity.CENTER);memo.addView(elapsed);start=primary(memo,"开始录音",this::begin);stop=button(memo,"停止并保存",this::save);stop.setEnabled(false);}
 private void begin(){if(recorder!=null||saving)return;if(checkSelfPermission("android.permission.RECORD_AUDIO")!=android.content.pm.PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{"android.permission.RECORD_AUDIO"},31);return;}try{pending=File.createTempFile("voice-memo-",".m4a",getCacheDir());recorder=new MediaRecorder();recorder.setAudioSource(MediaRecorder.AudioSource.MIC);recorder.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);recorder.setAudioEncoder(MediaRecorder.AudioEncoder.AAC);recorder.setAudioSamplingRate(16000);recorder.setAudioEncodingBitRate(64000);recorder.setOutputFile(pending.getPath());recorder.prepare();recorder.start();started=SystemClock.elapsedRealtime();start.setEnabled(false);stop.setEnabled(true);notice.setText("● 手机麦克风正在录音");clock.post(tick);}catch(Exception e){release();if(pending!=null)pending.delete();notice.setText("无法开始录音，请检查麦克风权限和可用空间");}}
 private void save(){if(saving)return;if(recorder==null){if(pending!=null&&pending.isFile())persist();return;}clock.removeCallbacks(tick);saving=true;stop.setEnabled(false);boolean good=true;try{recorder.stop();}catch(Exception e){good=false;}release();if(!good){saving=false;if(pending!=null)pending.delete();notice.setText("录音过短，尚未保存，请重新开始");start.setEnabled(true);return;}persist();}
 private void persist(){saving=true;start.setEnabled(false);stop.setEnabled(false);final File source=pending;final String[] id={""};background(()->{try{id[0]=savedId.isEmpty()?store.importUri(android.net.Uri.fromFile(source)):savedId;savedId=id[0];store.update("audio",id[0],"title","语音备忘 · "+new java.text.SimpleDateFormat("M/d HH:mm",java.util.Locale.CHINA).format(new java.util.Date()));OfflineScheduler.enqueue(store,id[0]);OfflineScheduler.schedule(this);if(new SecureSettings(this).vadRequested()){store.addJob(id[0],"vad",new org.json.JSONObject());startJobs();}source.delete();}catch(Exception e){saving=false;runOnUiThread(()->{start.setText("重试保存");start.setEnabled(true);start.setOnClickListener(v->save());});throw e;}},()->{setResult(RESULT_OK,new Intent().putExtra("id",id[0]));finish();});}
 private void release(){if(recorder!=null){recorder.release();recorder=null;}}
 public void onRequestPermissionsResult(int request,String[] permissions,int[] granted){super.onRequestPermissionsResult(request,permissions,granted);if(request==31){if(granted.length>0&&granted[0]==android.content.pm.PackageManager.PERMISSION_GRANTED)begin();else notice.setText("未授予麦克风权限，可返回后导入现有录音");}}
 protected void onPause(){if(recorder!=null)save();super.onPause();}
 public void onDestroy(){clock.removeCallbacksAndMessages(null);release();super.onDestroy();}
}
